module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // States for the Moore machine:
    // S0: Saw no '1' yet (or reset state). Output for '1' is 1, for '0' is 0.
    // S1: Saw at least one '1'. Output is inverted (0 for 1, 1 for 0).
    // Actually, let's use standard Mealy/Moore convention for 2's complement:
    // State represents whether we have seen the first '1' yet.
    // S0: First '1' not yet seen (or just starting). 
    //     - If x=0, output is 0, stay in S0.
    //     - If x=1, output is 1, go to S1.
    // S1: First '1' has been seen.
    //     - If x=0, output is 1, stay in S1.
    //     - If x=1, output is 0, stay in S1.
    //
    // Since the prompt asks for a Moore state machine, the output depends *only* on the current state.
    // Let's refine the states to be strictly Moore:
    // S_ZERO: Output is 0. We haven't seen the first '1' yet, OR we are past it and outputting 0.
    // Wait, let's trace:
    // Input sequence: 0 1 0 0 (binary 4, 2's comp is -4: 1 1 0 0)
    // LSB first: x = 0, 1, 0, 0
    // Expected z:
    // x=0 -> z=0 (still in 'waiting for first 1' state, output 0)
    // x=1 -> z=1 (this is the first 1, output 1, now transition to state where we invert)
    // x=0 -> z=0 (invert 0 -> 0? Wait! 2's comp of 0100 is 1100. LSBs: x=0 -> z=0, x=1 -> z=1, x=0 -> z=0, x=0 -> z=0).
    // Wait, 4 in binary is 0100. 2's complement is 1100. LSB to MSB:
    // x: 0, 1, 0, 0
    // z: 0, 1, 0, 0.
    // Let's check x=2: binary 0010. 2's comp: 1110. LSB to MSB:
    // x: 0, 1, 0, 0
    // z: 0, 1, 1, 1.
    // Let's use a 3-state or 4-state Moore machine if needed, or standard 2-state with registered output:

    // States:
    // S_IDLE / S_INIT: output 0. If x=0 stay, if x=1 go to S_ONE.
    // S_ONE: output 1. (This handles the first '1'). From here, next state depends on x:
    //   if x=0 -> go to S_ZERO_INV (output 0)
    //   if x=1 -> go to S_ONE_INV (output 1)
    // S_ZERO_INV: output 0.
    //   if x=0 -> go to S_ZERO_INV (output 0)
    //   if x=1 -> go to S_ONE_INV (output 1)
    // S_ONE_INV: output 1.
    //   if x=0 -> go to S_ZERO_INV (output 0)
    //   if x=1 -> go to S_ONE_INV (output 1)

    parameter S0 = 2'd0; // Output 0, first 1 not seen
    parameter S1 = 2'd1; // Output 1, first 1 seen (and it was 1, so output 1, next is inverted)
    parameter S2 = 2'd2; // Output 0, post-first-1, invert 0->0
    parameter S3 = 2'd3; // Output 1, post-first-1, invert 1->0 (wait, output is 1, so invert 0->1)

    // Let's simplify:
    // A Moore machine has outputs determined entirely by the state.
    // State encoding:
    // 2'b00: Output 0, waiting for first 1.
    // 2'b01: Output 1, first 1 encountered (so output is 1).
    // 2'b10: Output 0, past first 1, current output is 0.
    // 2'b11: Output 1, past first 1, current output is 1.

    reg [1:0] state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 2'b00;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            2'b00: begin // Output is 0
                if (x) next_state = 2'b01; // first 1 -> output becomes 1
                else   next_state = 2'b00; // keep 0
            end
            2'b01: begin // Output is 1 (the first 1 itself)
                if (x) next_state = 2'b11; // next output will be 1 (invert 0)
                else   next_state = 2'b10; // next output will be 0 (invert 1)
            end
            2'b10: begin // Output is 0
                if (x) next_state = 2'b11; // invert 0 -> 1
                else   next_state = 2'b10; // invert 1 -> 0
            end
            2'b11: begin // Output is 1
                if (x) next_state = 2'b11; // invert 0 -> 1
                else   next_state = 2'b10; // invert 1 -> 0
            end
            default: next_state = 2'b00;
        endcase
    end

    // Moore output depends only on state
    assign z = state[0]; // 00->0, 01->1, 10->0, 11->1? Wait:
    // Let's check state[0]:
    // 2'b00 -> 0
    // 2'b01 -> 1
    // 2'b10 -> 0
    // 2'b11 -> 1
    // Matches our intended outputs!

endmodule
```

